{
  "name": "被动监测实验界面后端",
  "name_en": "Passive Monitoring GUI Backend",
  "manufacturer": "",
  "description": "一个非物理的软件组件，用于被动监测实验的界面与通信协调。它负责通过 VISA 连接并配置 Keithley 2400、Keithley 2182 和 Lakeshore 温控相关仪器，读取测量值与温度数据，并管理实验启动、停止、日志和界面状态。",
  "description_en": "A non-physical software component for coordinating the GUI and instrument communication in a passive monitoring experiment. It connects to and configures Keithley 2400, Keithley 2182, and Lakeshore temperature-control-related instruments over VISA, acquires measurement and temperature data, and manages experiment start/stop, logging, and UI state.",
  "tag_hints": [
    "passive monitoring",
    "GUI experiment control",
    "VISA instrument communication",
    "Keithley 2400",
    "Keithley 2182",
    "Lakeshore temperature readout",
    "measurement logging"
  ],
  "actions": [
    {
      "action_name": "auto-configure_instruments",
      "description": "配置被动监测实验所需的 Keithley 2400、Keithley 2182 和 Lakeshore 仪器参数。",
      "description_en": "Configure the Keithley 2400, Keithley 2182, and Lakeshore instrument settings for passive monitoring."
    },
    {
      "action_name": "auto-connect",
      "description": "连接用于被动监测的 Keithley 2400、Keithley 2182 和 Lakeshore 仪器。",
      "description_en": "Connect to the Keithley 2400, Keithley 2182, and Lakeshore instruments used for passive monitoring."
    },
    {
      "action_name": "auto-shutdown",
      "description": "关闭被动监测会话并安全结束相关仪器通信。",
      "description_en": "Shut down the passive monitoring session and safely terminate communication with the related instruments."
    },
    {
      "action_name": "auto-get_measurement",
      "description": "获取测量数据。",
      "description_en": "Get measurement data."
    },
    {
      "action_name": "auto-setup_styles",
      "description": "设置被动监测界面的显示样式。",
      "description_en": "Set up the display styles for the passive monitoring interface."
    },
    {
      "action_name": "auto-create_widgets",
      "description": "创建被动监测界面的控件组件。",
      "description_en": "Create the widget components for the passive monitoring interface."
    },
    {
      "action_name": "auto-log",
      "description": "记录实验过程中的日志信息。",
      "description_en": "Record log information during the experiment."
    },
    {
      "action_name": "auto-start_experiment",
      "description": "启动被动监测实验流程。",
      "description_en": "Start the passive monitoring experiment workflow."
    },
    {
      "action_name": "auto-stop_experiment",
      "description": "停止被动监测实验流程。",
      "description_en": "Stop the passive monitoring experiment workflow."
    },
    {
      "action_name": "auto-set_ui_state",
      "description": "设置界面的当前状态。",
      "description_en": "Set the current state of the user interface."
    }
  ]
}

